 if(tab==='My account')html=`<div class="card"><h2>Mobile + PIN login</h2><p>Registered email: ${esc(state.user.loginEmail||'Not set')}<br>Mobile: ${esc(state.user.phone||'Not set')}</p><p class="muted">Email OTP stays available if your account has an email. Register your mobile and set a private 6–12 digit PIN here. PIN changes sign out other existing sessions.</p><button id="changePin">Set / change my mobile PIN</button></div>`;
 if(tab==='Employees'||tab==='User Access'){const employees=matchingEmployees(state.employees,search);html=`<div class="toolbar"><button data-new-employee>+ Add employee</button><input id="employeeSearch" type="search" placeholder="Search employee name / department / email / mobile" aria-label="Search employees" value="${esc(search)}"><small>${employees.length} of ${state.employees.length} employees</small></div><p class="muted">Add login email/mobile and form permissions. Owner account is configured separately.</p><div class="card table-wrap"><table><thead><tr><th>Name</th><th>Department</th><th>Email / mobile / access</th><th>Action</th></tr></thead><tbody>${employees.map(e=>`<tr><td>${esc(e.name)}</td><td>${esc(e.department)}</td><td>${esc(e.email||'Email not set')}<small>${esc(e.phone||'Mobile not set')}</small><small>${esc(e.role)} · ${e.active?'Active':'Inactive'} · ${esc((e.forms||[]).join(', '))}</small></td><td><button data-employee="${esc(e.id)}">Configure</button>${plant()?`<button class="danger" data-delete-employee="${esc(e.id)}">Remove employee</button>`:''}</td></tr>`).join('')}</tbody></table>${!employees.length?'<div class="empty">'+(state.employees.length?'No matching employee. Try another name or department.':'No employees added yet.')+'</div>':''}</div>`;}
 if(tab==='Daily routines')html=routinesHtml();
