 for(const [selector,handler] of [['#reportType',e=>{reportType=e.target.value;page=0;search='';render();}],['#reportSearch',e=>searchChange(e,'reportSearch')],['#taskSearch',e=>searchChange(e,'taskSearch')],['#routineSearch',e=>searchChange(e,'routineSearch')],['#employeeSearch',e=>searchChange(e,'employeeSearch')]]){const el=$(selector);if(el)el[selector==='#reportType'?'onchange':'oninput']=handler;}
