function searchChange(e,id){const pos=e.target.selectionStart;search=e.target.value;page=0;render();const el=$('#'+id);el.focus();if(el.type!=='search'&&pos!==null)el.setSelectionRange(pos,pos);}
function modal(title,html){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();}
async function mutate(action,data={}){const r=await api(action,data,true);$('#dialog').close();void load();return r;}
function submit(form,fn){form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button[type=submit]')||form.querySelector('button');if(b.disabled)return;const label=b.textContent;let status=form.querySelector('[data-save-status]');if(!status){status=document.createElement('p');status.dataset.saveStatus='';status.setAttribute('role','status');status.setAttribute('aria-live','polite');form.append(status);}status.textContent='Saving… Please wait for confirmation.';b.disabled=true;b.textContent='Saving…';try{await fn(new FormData(form));status.textContent='Successfully saved';}catch(err){status.textContent=err.message==='Unknown action'?'Apps Script backend needs the latest Code.gs. Deploy > Manage deployments > Edit > New version > Deploy, then retry.':err.message;message(status.textContent);}finally{b.disabled=false;b.textContent=label;}};}
function inputField(k,value=''){let options=k==='Material Name'?MATERIALS:k==='Meter Name'?METERS:k==='Stock Unit'?['Bags','kg','litres','Nos']:k==='Container Type'?['Can','Barrel']:k==='Used For'?['DG','Forklift']:k==='Status'?['Pending','In progress','Completed']:null;const optional=['Steam Pressure (bar)','Feed Water Temperature (C)','Flue Gas T1 (C)','Flue Gas T2 (C)','Test Time','Fuel Meter Reading','Steam Meter Reading','Calculated Water (litres)','Calculated Fuel (kg)','Calculated Steam (kg)','Reading Day Offset','Hardness (ppm)','Breakdown Reason','Reason','Colour Changes','Starch per Bag (kg)','Starch per Batch (kg)'].includes(k);return `<label>${esc(k)}${options?`<select name="${esc(k)}">${option(options,value||options[0])}</select>`:`<input name="${esc(k)}" type="${inputType(k)}" ${inputType(k)==='number'?'min="0" step="any"':''} value="${esc(value)}" ${optional?'':'required'}>`}</label>`;}
function entryForm(r){const type=r?.type||reportType;if(!reportPermission(r?'correct':'entry',type))return message(r?'Correction permission required':'Entry form permission required');if(!r&&type==='Boiler'){tab='Boiler Entry';boilerEntryType=reportType;render();return;}const fields=r?.fields||{},date=r?.date||dateIST();modal(r?'Correct '+type:'New '+type,`<form id="entryForm"><div class="form-grid"><label>Date<input name="date" type="date" value="${date}" required></label><label>Shift<select name="shift">${option(['Day','Night','Daily'],r?.shift||'Daily')}</select></label>${fieldNames(type).filter(k=>(type!=='DG Operation'||k!=='Diesel Consumption (litres)')&&(type!=='Diesel Consumption'||k!=='Issued Litres')).map(k=>inputField(k,fields[k]??(k==='Reading Multiplier'?'1':k==='Starch per Bag (kg)'?'50':k==='Starch per Batch (kg)'?(date<'2026-09-10'?'200':'150'):''))).join('')}${type==='Water Meter'?'<p id="waterOpeningNote" class="full notice">Opening reading will be fetched from the previous meter closing.</p>':''}${type==='Diesel Consumption'?'<p class="full notice">Enter Can and Barrel counts for Opening, Receiving and Issue. 1 Can = 35 litres; 1 Barrel = 200 litres. Enter 0 where none. Save a separate entry for each receiver/use. Reports show litres. <strong id="dieselIssue"></strong></p>':''}${type==='DG Operation'?'<p class="full notice">Fixed diesel rate: 26 litres/hour. Enter duration as HH:MM (01:30 = 1 hour 30 minutes). <strong id="dgConsumption"></strong></p>':''}<label class="full">Remarks<textarea name="Remarks">${esc(fields.Remarks)}</textarea></label>${r?'<label class="full">Correction reason<textarea name="reason" required></textarea></label>':''}</div><div class="form-actions"><button type="submit">Save report</button></div></form>`);const f=$('#entryForm');if(type==='Water Meter'&&!r)setupWaterOpening(f);if(type==='Diesel Consumption'){const keys=['Opening Cans','Opening Barrels','Received Cans','Received Barrels','Issued Cans','Issued Barrels'];const preview=()=>{const litres=stage=>Number(f.elements.namedItem(stage+' Cans').value)*35+Number(f.elements.namedItem(stage+' Barrels').value)*200;const opening=litres('Opening'),received=litres('Received'),issued=litres('Issued');$('#dieselIssue').textContent='Opening: '+opening+' L | Received: '+received+' L | Issued: '+issued+' L | Closing: '+(opening+received-issued)+' L';};keys.forEach(k=>{const el=f.elements.namedItem(k);el.step='1';el.max='10000';el.addEventListener('input',preview);});preview();}if(type==='DG Operation'){const duration=f.elements.namedItem('Duration (HH:MM)');duration.placeholder='01:30';duration.pattern='[0-9]{1,2}:[0-5][0-9]';duration.inputMode='text';const preview=()=>{const match=duration.value.match(/^(\d{1,2}):([0-5]\d)$/);$('#dgConsumption').textContent=match?'Calculated diesel: '+((Number(match[1])*60+Number(match[2]))*26/60).toFixed(2)+' litres':'';};duration.addEventListener('input',preview);preview();}submit(f,async fd=>{const values={};fieldNames(type).concat('Remarks').forEach(k=>values[k]=fd.get(k));await mutate(r?'correctReport':'saveReport',{id:r?.id,version:r?.version,type,date:fd.get('date'),shift:fd.get('shift'),fields:values,reason:fd.get('reason')});message(r?'Correction saved':'Report saved');});}
function setupWaterOpening(form){const meter=form.elements.namedItem('Meter Name'),date=form.elements.namedItem('date'),shift=form.elements.namedItem('shift'),opening=form.elements.namedItem('Opening Reading');let sequence=0,manual=false,autoValue='';opening.addEventListener('input',()=>{manual=true;});async function fetchOpening(){const request=++sequence,note=form.querySelector('#waterOpeningNote');if(!manual&&opening.value===autoValue)opening.value='';note.textContent='Looking up previous closing…';try{const result=await api('waterOpening',{meter:meter.value,date:date.value,shift:shift.value});if(request!==sequence||!form.isConnected)return;if(result.found){if(!manual){opening.value=result.reading;autoValue=result.reading;}note.textContent=(manual?'Previous closing (manual opening retained): ':'Opening fetched: ')+result.reading+' · '+result.date+' · '+result.shift+'. Verify before saving.';}else note.textContent=result.message||'No previous record for this meter. Enter opening manually.';}catch(err){if(request===sequence&&form.isConnected)note.textContent='Could not fetch opening: '+err.message+'. Enter verified opening manually.';}}[meter,date,shift].forEach(el=>el.addEventListener('change',fetchOpening));fetchOpening();}
