 if($('#editReport'))$('#editReport').onclick=()=>portalCorrectionForm(r);if($('#deleteReport'))$('#deleteReport').onclick=async()=>{const reason=prompt('Delete this entry from portal reports and KPIs? Original Sheet and history are retained. Enter reason:');if(!reason?.trim())return;try{await mutate('removeReport',{id:r.id,version:r.version,reason});message('Entry deleted from portal. History retained.');}catch(e){message(e.message);}};
 if($('#followTask'))$('#followTask').onclick=()=>taskForm(null,r.id);if($('#approveReport'))$('#approveReport').onclick=async()=>{const mode=r.status==='Approved'?'reopen':'approve',reason=mode==='reopen'?prompt('Reason for reopening'):'';if(mode==='reopen'&&!reason)return;try{await mutate('reviewReport',{id:r.id,version:r.version,mode,reason});message(mode==='approve'?'Successfully Approved':'Report Reopened for Correction');}catch(e){message(e.message);}};
 const form=$('#remarkForm');if(form.elements.createTask)form.elements.createTask.onchange=()=>form.elements.due.required=form.elements.createTask.checked;if(form.elements.due)form.elements.due.required=true;
 submit(form,async fd=>{const due=fd.get('due');await mutate('remark',{id:r.id,text:fd.get('text'),assignee:fd.get('assignee'),createTask:fd.get('createTask')==='on',due:due?due+':00+05:30':''});message('Remark saved'+(fd.get('createTask')==='on'?' and task assigned':''));});
