async function exportPdf(){const b=$('#pdf');b.disabled=true;message('Fetching report records…');try{const snapshot=await api('exportReports',{from:$('#from').value,to:$('#to').value,type:reportType,shift:reportType==='Glue Consumption'?'All':$('#shift').value,review:$('#review').value,includeHistory:false});const reportIds=snapshot.reports,events=snapshot.activity;if(!reportIds.length)throw Error('No report records in this range.');message('Preparing PDF…');const [regular,bold]=await Promise.all(['report-font.ttf','report-font-bold.ttf'].map(f=>fetch('./'+f).then(r=>{if(!r.ok)throw Error('PDF font unavailable');return r.arrayBuffer();})));await ensurePdf();const {createReportPdf}=await import('./report-pdf.js');const bytes=await createReportPdf({type:reportType,from:$('#from').value,to:$('#to').value,approved:$('#review').value==='Approved',reports:reportIds,activity:events,generated:new Date().toISOString(),shift:$('#shift').value,machine:'',history:false,batchChangeover:state.batchChangeover,table:buildReportTable(reportType,reportIds,{mode:tableMode,changeover:state.batchChangeover,visibleColumns:state.reportColumns?.[reportType]})},new Uint8Array(regular),new Uint8Array(bold));const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download=`Starish_${reportType.replace(/\s/g,'_')}_${$('#from').value}_${$('#to').value}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);message('PDF downloaded');}catch(e){message(e.message);}finally{b.disabled=false;}}
