function simpleTasksHtml(){const tasks=scopedTasks().filter(t=>t.status!=='Removed');return `<div class="toolbar">${taskEmployeePicker()}<button data-new-task>+ Assign task</button>${plant()?'<button id="portalSettings" class="secondary">Management settings</button><button data-tab="User Access" class="secondary">User Access</button>':''}</div><div class="card table-wrap excel-report"><table><thead><tr><th>Employee</th><th>Task</th><th>Type</th><th>Status</th><th>Priority</th><th>Deadline</th><th>Pending reason</th><th>Action</th></tr></thead><tbody>${tasks.map(t=>`<tr><td>${esc((state.users||[]).find(u=>u.email===t.assignee)?.name||t.assignee)}</td><td>${esc(t.title)}</td><td>${esc(taskKind(t)==='daily'?'Daily task':taskKind(t)==='assigned'?'Assigned task':'Additional task')}</td><td>${['Submitted','Closed'].includes(t.status)?'<span class="badge approved">✓ Completed</span><small>'+(t.status==='Submitted'?'Awaiting review':'Approved')+'</small>':'<span class="badge">Pending</span>'}${t.removalRequest?.status==='Requested'?'<small>Removal approval requested</small>':''}</td><td>${esc(t.priority||'Medium')}</td><td>${esc(t.due.slice(0,10))}</td><td>${esc(t.pendingReason||'')}</td><td><button data-task="${esc(t.id)}">Review</button>${plant()?`<button class="danger" data-delete-task="${esc(t.id)}">Delete task</button>`:''}</td></tr>`).join('')}</tbody></table>${!tasks.length?'<p class="empty">No employee tasks.</p>':''}</div>`;}
function columnSettings(){const model=buildReportTable(reportType,filtered(),{mode:tableMode,changeover:state.batchChangeover}),selected=state.reportColumns?.[reportType]||model.allColumns;modal('Report columns - '+reportType,`<form id="columnsForm">${model.allColumns.map(k=>`<label class="check"><input type="checkbox" name="columns" value="${esc(k)}" ${selected.includes(k)?'checked':''}>${esc(k)}</label>`).join('')}<button type="submit">Save columns for everyone</button></form>`);submit($('#columnsForm'),async fd=>{const columns=fd.getAll('columns');if(!columns.length)throw Error('Select at least one column');const type=reportType;await api('setReportColumns',{type,columns},true);state.reportColumns={...state.reportColumns,[type]:columns};$('#dialog').close();render();message('Report columns saved');void load();});}
